style.css:
/* Fundo da página inicial */
body {
    background: url("https://i.pinimg.com/736x/a9/69/f0/a969f01d55fe5b033a10b511fd45a2ca.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
}

/* Barra de pesquisa */
input[name="q"] {
    background: rgba(255, 192, 203, 0.2) !important;
    border: 2px solid #ffb6c1 !important;
    color: #ffb6c1 !important;
}

input[name="q"]::placeholder {
    color: #ffb6c1 !important;
}
